module bulkhead_planner(input clk,input rst_n,input start,input [2:0] num_vertices,input [31:0] min_area,input [31:0] vertices_x [0:7],input [31:0] vertices_y [0:7],output reg [2:0] M,output reg [31:0] bulkhead_x [0:6],output reg [2:0] bulkhead_count,output reg done);localparam IDLE = 3'd0;localparam CALC_TOTAL_AREA = 3'd1;localparam FIND_M = 3'd2;localparam CALC_TARGET = 3'd3;localparam PLACE_BULKHEADS = 3'd4;localparam DONE = 3'd5;reg [2:0] state,next_state;reg [31:0] total_area_reg;reg [2:0] M_reg;reg [31:0] target_area_reg;reg [31:0] bulkhead_x_reg [0:6];reg [2:0] bulkhead_count_reg;reg done_reg;reg [2:0] current_bulkhead;wire [63:0] sum_terms;always @(*) begin case(num_vertices)3:begin sum_terms = (vertices_x[0] * vertices_y[1] - vertices_x[1] * vertices_y[0]) + (vertices_x[1] * vertices_y[2] - vertices_x[2] * vertices_y[1]) + (vertices_x[2] * vertices_y[0] - vertices_x[0] * vertices_y[2]);end default:sum_terms = 64'd0;endcase end assign abs_sum_terms = (sum_terms >= 64'd0) ? sum_terms : ~sum_terms + 1'd1; assign total_area = abs_sum_terms >> 17; always @(posedge clk or negedge rst_n) begin if(!rst_n) begin state <= IDLE; next_state <= IDLE; total_area_reg <= 32'd0; M_reg <= 3'd0; target_area_reg <= 32'd0; bulkhead_x_reg <= 32'd0; bulkhead_count_reg <= 3'd0; done_reg <= 1'b0; current_bulkhead <= 3'd0; end else begin state <= next_state; case(state) IDLE:if(start) next_state <= CALC_TOTAL_AREA;else next_state <= IDLE; CALC_TOTAL_AREA:total_area_reg <= total_area; next_state <= FIND_M; FIND_M:if(total_area_reg < min_area) M_reg <= 3'd1;else begin M_reg <= total_area_reg / min_area; if(M_reg > 3'd8) M_reg <= 3'd8; end next_state <= CALC_TARGET; CALC_TARGET:if(M_reg == 1) begin bulkhead_count_reg <= 3'd0; done_reg <= 1'b1; next_state <= DONE; end else begin target_area_reg <= total_area_reg / M_reg; next_state <= PLACE_BULKHEADS; end PLACE_BULKHEADS:bulkhead_count_reg <= M_reg - 1; next_state <= DONE; DONE:next_state <= DONE; endcase end end end assign M = M_reg; assign bulkhead_x = bulkhead_x_reg; assign bulkhead_count = bulkhead_count_reg; assign done = done_reg; endmodule